import type { Question } from '../questions';

export const MPPSC_SSE_2026_GENERAL_APTITUDE_FULL_1: Question[] = [
  { id: 'b15-002-apt-q001', section: 'General Aptitude Test', topic: 'Comprehension', difficulty: 'medium', question: 'A typing course replaced a public rank list with a private dashboard showing each learner\'s progress in speed, accuracy and error correction. Attendance improved and more beginners attempted optional practice sets.\n\nWhich change in feedback is described most accurately?', options: ['Learners stopped receiving any feedback.', 'Only the strongest learners saw results.', 'Practice tests were abolished.', 'Feedback shifted from comparison with others toward progress against skills.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The new dashboard compares each learner with skill targets and prior progress rather than ranking the learner against other people.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q002', section: 'General Aptitude Test', topic: 'Communication skills', difficulty: 'medium', question: 'A project note must tell four teams what to submit and when. Which format is clearest?', options: ['Put every instruction in one long paragraph without headings.', 'List deadlines but omit who is responsible.', 'Send different versions that use conflicting dates.', 'Use a short table with one row per team showing deliverable, owner and deadline.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'A structured owner-deliverable-deadline format makes the required action and accountability explicit.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q003', section: 'General Aptitude Test', topic: 'Decision making', difficulty: 'medium', question: 'A policy allows a fee waiver only for applicants meeting a stated income threshold. An applicant requests a waiver but provides no income evidence. Which response is most appropriate?', options: ['Grant the waiver based on sympathy alone.', 'Explain the evidence requirement and allow submission through the prescribed process.', 'Reject all future waiver requests.', 'Create a new threshold for this applicant.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The policy can be applied fairly only after the eligibility condition is evidenced.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q004', section: 'General Aptitude Test', topic: 'Profit, loss and discount', difficulty: 'medium', question: 'In an inter-district training exercise, An equipment kit costing ₹420 is marked 25% above cost and sold at a 15% discount on the marked price. What is the profit percentage on cost? Assume the listed conditions are exhaustive for this exercise.', options: ['25', '10', '6.25', '21.25'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Selling price = 420×1.25×0.85 = ₹446.25; profit% = 6.25%.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q005', section: 'General Aptitude Test', topic: 'Communication skills', difficulty: 'hard', question: 'A public-works monitoring team records these facts. A chart will be read by both specialists and non-specialists. Which caption is most useful? Use the given values without importing any unstated exception.', options: ['Describe colours without explaining what they represent.', 'Repeat the chart title without context.', 'State the measure, time period and the main comparison in plain language.', 'Use unexplained abbreviations only.'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'A caption should let readers understand what is measured, when, and what comparison matters.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q006', section: 'General Aptitude Test', topic: 'Communication planning', difficulty: 'hard', question: 'A flash-flood warning must reach a settlement where residents use three local languages, some households have no smartphones, and power may fail. Which communication plan is most appropriate?', options: ['Send one long message in the official language through a smartphone app only.', 'Wait for electricity to stabilize before issuing any warning.', 'Ask a single shopkeeper to pass the message informally.', 'Use the same verified warning through multiple channels, including translated voice/public-address messages, simple visual cues, and phone alerts where available.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'A time-critical warning should be consistent, multilingual and redundant across channels so that lack of one device, language or power source does not prevent access.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q007', section: 'General Aptitude Test', topic: 'Relative speed', difficulty: 'medium', question: 'A regional programme office faces this situation. Two buses leave opposite ends of a 300 km route at the same time, travelling toward each other at 54 km/h and 48 km/h. After how many minutes do they meet? Assume the listed conditions are exhaustive for this exercise.', options: ['3000', '2.94', '176.47', '206.47'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Closing speed = 102 km/h; meeting time = 300/102 h = 176.47 minutes.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q008', section: 'General Aptitude Test', topic: 'Coding-decoding', difficulty: 'medium', question: 'A code writes each word by moving its first letter to the end and then adding \'A\'. Under this rule, TRAIN becomes RAINTA. How is BLOCK coded?', options: ['BLOCKA', 'KCBLOA', 'LOCKAB', 'LOCKBA'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Move B to the end of LOCK to get LOCKB, then add A: LOCKBA.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q009', section: 'General Aptitude Test', topic: 'Communication skills', difficulty: 'easy', question: 'A citizen writes, \'My certificate problem is still there.\' Which reply best begins clarification?', options: ['Assume the problem is a payment failure.', 'Ask which certificate, what step has failed, and any reference number already issued.', 'Reply only that the office is busy.', 'Close the request because the message is brief.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The message is underspecified, so targeted questions about the item and failed step are needed before acting.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q010', section: 'General Aptitude Test', topic: 'Rate and unit conversion', difficulty: 'medium', question: 'A field vehicle covers 3.6 km in 4.5 minutes at a constant speed. What is its speed in kilometres per hour?', options: ['36', '42', '48', '54'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: '3.6 km in 4.5 minutes is 0.8 km per minute. Multiplying by 60 gives 48 km/h.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q011', section: 'General Aptitude Test', topic: 'Problem solving', difficulty: 'hard', question: 'A field team must visit villages P, Q and R. Road P-Q is closed. Roads P-R and R-Q are open, and the team must start at P and finish at Q. What route is feasible?', options: ['P → Q', 'P → R → Q', 'Q → R → P', 'P → Q → R'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The direct P-Q road is closed; the open two-leg path from P to Q goes through R.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q012', section: 'General Aptitude Test', topic: 'Spatial reasoning', difficulty: 'medium', question: 'A person faces north, turns 90° right, then 135° left. Which direction is the person facing?', options: ['North-east', 'South-west', 'North-west', 'South-east'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'North → east after 90° right; turning 135° left from east points north-west.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q013', section: 'General Aptitude Test', topic: 'Syllogistic reasoning', difficulty: 'medium', question: 'Every inspected bridge is mapped. Some mapped assets are not bridges. No unmapped asset is scheduled for repair. Which conclusion must be true?', options: ['Every mapped asset is a bridge.', 'Some scheduled assets are unmapped.', 'Every inspected bridge is mapped.', 'No mapped asset can be scheduled for repair.'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The first premise directly guarantees that every inspected bridge is mapped; the other conclusions do not follow.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q014', section: 'General Aptitude Test', topic: 'Interpersonal skills', difficulty: 'medium', question: 'For a state-level service audit, During a team briefing, one member repeatedly misunderstands a task. What is the best first response? Use the given values without importing any unstated exception.', options: ['Restate the task in simpler terms and ask the member to explain it back.', 'Ignore the misunderstanding until the deadline.', 'Assign blame in front of the group.', 'Repeat the same words more loudly.'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Clear restatement plus a teach-back check tests whether the message has actually been understood.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q015', section: 'General Aptitude Test', topic: 'Fractions and capacity', difficulty: 'medium', question: 'A storage tank is 3/5 full. After 120 litres are added, it becomes 3/4 full. What is the tank\'s total capacity?', options: ['600 litres', '800 litres', '900 litres', '1,000 litres'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The added 120 litres represents 3/4−3/5 = 3/20 of the tank. Therefore capacity = 120×20/3 = 800 litres.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q016', section: 'General Aptitude Test', topic: 'Counting along intervals', difficulty: 'medium', question: 'Reflective posts are placed along one side of a 300-metre road at intervals of 25 metres, with a post at both ends. How many posts are required?', options: ['11', '12', '13', '14'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'There are 300/25 = 12 equal intervals. Including both endpoints requires one more post than intervals, so 13 posts are needed.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q017', section: 'General Aptitude Test', topic: 'Pipes and cisterns', difficulty: 'medium', question: 'Pipe A fills 1/6 of a tank per hour. Pipe B fills 1/9 per hour. A runs alone for 2 hours, then both run together. How long after B is opened does the tank become full?', options: ['2 hours', '3 hours', '2.4 hours', '3.6 hours'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'After 2 h A fills 1/3, leaving 2/3. Combined rate=5/18 per h, so time=(2/3)/(5/18)=12/5=2.4 h.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q018', section: 'General Aptitude Test', topic: 'Comprehension', difficulty: 'medium', question: 'An online permit portal added a prominent checklist showing the documents most often omitted from applications. Calls asking which documents were required fell, but calls about eligibility rules were unchanged.\n\nWhich inference follows most directly?', options: ['Making common information easier to find can reduce repetitive simple queries.', 'Complex queries became more common because of the change.', 'The repeated question was impossible to answer online.', 'Web information eliminates all support calls.'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Making a frequently requested piece of routine information easier to find can reduce repetitive simple queries without eliminating more complex questions.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q019', section: 'General Aptitude Test', topic: 'Decision making', difficulty: 'hard', question: 'A grant guideline permits late documents only when a system outage is recorded. An applicant claims the portal failed, but no outage is shown in the log. What should the officer do first?', options: ['Check the applicant\'s evidence and the technical records before deciding whether the exception applies.', 'Approve the exception automatically.', 'Reject the applicant without examining any evidence.', 'Alter the outage log to match the claim.'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The exception depends on a factual condition, so the officer should verify the relevant evidence before applying or denying it.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q020', section: 'General Aptitude Test', topic: 'Constraint reasoning', difficulty: 'hard', question: 'For a revenue-office analytical exercise, A delivery can use route X only when road R is open; route Y is always available. Road R is closed. Which option remains feasible under the stated constraint? Use the given values without importing any unstated exception.', options: ['Use route X and assume R is open.', 'Use route Y.', 'No route is available.', 'Use route X.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The closure blocks X, while Y is explicitly stated to be always available.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q021', section: 'General Aptitude Test', topic: 'Data interpretation', difficulty: 'medium', question: 'A service counter records cumulative tokens served as 84 at 10:00, 137 at 12:00, 191 at 14:00 and 236 at 16:00. How many tokens were served from 12:00 to 16:00?', options: ['91', '99', '107', '152'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Cumulative service rose from 137 at 12:00 to 236 at 16:00, so 236 − 137 = 99 tokens were served in that interval.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q022', section: 'General Aptitude Test', topic: 'Inference', difficulty: 'hard', question: 'In a public-administration workshop, All three tested samples from a batch passed a quality check. Which conclusion is justified without overgeneralising? Assume the listed conditions are exhaustive for this exercise.', options: ['The entire batch certainly passes.', 'The entire batch certainly fails.', 'Testing any further item is logically impossible.', 'The three tested samples passed; the untested items may or may not pass.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The evidence directly establishes only the tested samples; it does not prove the status of every untested item.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q023', section: 'General Aptitude Test', topic: 'Averages', difficulty: 'medium', question: 'The average of five readings is 42. Four readings are 38, 41, 44 and 47. What is the fifth reading?', options: ['36', '40', '42', '50'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Total of five =210. The four given sum to 170, so the fifth is 40.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q024', section: 'General Aptitude Test', topic: 'Classification', difficulty: 'easy', question: 'A state training academy poses this problem. Which item does not belong with the other three? The state academy requires a conclusion from the stated data alone.', options: ['Parallelogram', 'Rectangle', 'Square', 'Triangle'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Square, rectangle and parallelogram are quadrilaterals; a triangle has three sides.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q025', section: 'General Aptitude Test', topic: 'Simple interest', difficulty: 'easy', question: 'A sum earns ₹1,680 simple interest in 4 years at 7% per year. What is the principal?', options: ['₹5,600', '₹6,400', '₹6,000', '₹7,000'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'P=I×100/(RT)=1680×100/(7×4)=₹6,000.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q026', section: 'General Aptitude Test', topic: 'Decision making and integrity', difficulty: 'medium', question: 'An officer evaluating bids discovers that one bidder is a company in which the officer\'s sibling has a financial interest. The rules require evaluators to disclose conflicts and recuse when impartiality may reasonably be questioned. What is the best action?', options: ['Continue silently because the officer has not received money.', 'Score only the technical section and ignore the conflict.', 'Ask the sibling which bidder deserves the contract.', 'Disclose the relationship and follow the recusal procedure before further evaluation.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The stated rule requires disclosure and recusal where impartiality may reasonably be questioned.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q027', section: 'General Aptitude Test', topic: 'Comprehension', difficulty: 'medium', question: 'A permit office used to release completed applications one by one. It changed to two fixed dispatch times each day. Average processing time inside the office was unchanged, but applicants received fewer unpredictable notification times and staff made fewer interruptions for dispatch.\n\nWhich conclusion is best supported?', options: ['Batching dispatch can reduce interruption and make delivery timing more predictable even when processing speed is unchanged.', 'Fixed dispatch times necessarily reduce the number of applications processed.', 'Applicants prefer every form of delay to immediate notification.', 'Processing time must have fallen because interruptions fell.'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The passage reports unchanged processing time alongside fewer dispatch interruptions and more predictable notification timing.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q028', section: 'General Aptitude Test', topic: 'Counting', difficulty: 'medium', question: 'A planning diagram places checkpoints at the vertices of a convex polygon and draws a connector between every pair of non-adjacent checkpoints. Exactly 65 connectors are drawn. How many checkpoints are there?', options: ['13', '12', '14', '15'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'For n vertices, the number of diagonals is n(n−3)/2. Thus n(n−3)/2 = 65, so n²−3n−130 = 0 = (n−13)(n+10). The positive solution is n = 13.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q029', section: 'General Aptitude Test', topic: 'हिंदी शब्दज्ञान', difficulty: 'medium', question: '“निष्पक्ष निर्णय” में “निष्पक्ष” शब्द का सही अर्थ क्या है?', options: ['जो निर्णय न ले', 'जो केवल एक पक्ष सुने', 'जो किसी पक्ष का अनुचित समर्थन न करे', 'जो बहुत कठोर हो'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: '“निष्पक्ष” का अर्थ है बिना पक्षपात के, किसी पक्ष का अनुचित समर्थन किए बिना निर्णय करना।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q030', section: 'General Aptitude Test', topic: 'Conditional reasoning', difficulty: 'hard', question: 'A rule states: if a laboratory sample is accepted, then both its label is legible and its seal is intact. Sample X has a damaged seal. What follows necessarily?', options: ['Sample X was not accepted.', 'Sample X has an illegible label.', 'Every rejected sample has a damaged seal.', 'A damaged seal proves the label is illegible.'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Acceptance implies an intact seal. By contraposition, a sample with a non-intact seal cannot have been accepted.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q031', section: 'General Aptitude Test', topic: 'Work rate', difficulty: 'hard', question: 'A team completes one survey in 12 days. After 4 days, another identical team joins. How many more days are needed to finish the remaining work?', options: ['3 days', '6 days', '8 days', '4 days'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'First team completes 4/12=1/3. Remaining 2/3 at twice the rate takes (2/3)/(2/12)=4 days.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q032', section: 'General Aptitude Test', topic: 'Mensuration', difficulty: 'medium', question: 'A rectangular notice board is 1.8 m by 1.2 m. A border 0.1 m wide is painted inside all four edges. What area remains unpainted in the centre?', options: ['1.76 m²', '1.80 m²', '1.60 m²', '2.16 m²'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Inner dimensions are 1.6 m by 1.0 m, so the central area is 1.60 m².', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q033', section: 'General Aptitude Test', topic: 'Series', difficulty: 'medium', question: 'A state data-review team is given this case. A sequence starts 3, 6, 12, 24, … and each term is double the previous one. What is term 8? The state academy requires a conclusion from the stated data alone.', options: ['384', '192', '24', '768'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Term 8 is 3×2^(7) = 384.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q034', section: 'General Aptitude Test', topic: 'Comprehension and evidence', difficulty: 'hard', question: 'A pilot survey tested a new questionnaire in two villages. Response rates were high, but most respondents were already members of local self-help groups. The survey team therefore decided not to estimate district-wide attitudes from the pilot alone.\n\nWhy was that decision methodologically sound?', options: ['High response rates always make a sample unrepresentative.', 'Self-help-group members cannot answer questionnaires accurately.', 'District attitudes can be known only through a census.', 'The pilot participants may not represent residents who are outside those groups.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The concern is representativeness: a sample concentrated among group members may not generalize to the wider district.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q035', section: 'General Aptitude Test', topic: 'Resource arithmetic', difficulty: 'medium', question: 'Each field kit requires 3 maps and 2 battery packs. A store has 29 maps and 19 battery packs. What is the maximum number of complete field kits that can be assembled?', options: ['9', '8', '10', '11'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Maps allow 29 ÷ 3 = 9 complete kits and battery packs allow 19 ÷ 2 = 9 complete kits. The limiting complete-kit count is therefore 9.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q036', section: 'General Aptitude Test', topic: 'Remainders', difficulty: 'easy', question: 'What is the remainder when 2^10 is divided by 7?', options: ['1', '3', '4', '2'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: '2^3≡1 (mod 7). Thus 2^9≡1 and 2^10≡2.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q037', section: 'General Aptitude Test', topic: 'Ratio and proportion', difficulty: 'easy', question: 'A map scale is 1:50,000. Two points are 7.4 cm apart on the map. What is the ground distance?', options: ['0.37 km', '3.7 km', '7.4 km', '37 km'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: '7.4×50,000 cm=370,000 cm=3.7 km.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q038', section: 'General Aptitude Test', topic: 'Series', difficulty: 'easy', question: 'For a state-level service audit, In the arithmetic sequence 10, 15, 20, …, what is the 11th term? Use the given values without importing any unstated exception.', options: ['60', '65', '61', '55'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'nth term = a+(n−1)d = 10+(11−1)×5 = 60.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q039', section: 'General Aptitude Test', topic: 'हिंदी व्याकरण', difficulty: 'easy', question: 'A municipal coordination cell considers this case. “लड़कियाँ खेल रही हैं” में क्रिया का वचन क्या है? The state academy requires a conclusion from the stated data alone.', options: ['द्विवचन', 'बहुवचन', 'एकवचन', 'कोई वचन नहीं'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: '“लड़कियाँ” बहुवचन है और “रही हैं” भी बहुवचन क्रिया है।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q040', section: 'General Aptitude Test', topic: 'Interpersonal skills', difficulty: 'medium', question: 'Two team members each believe the other missed a handoff. What is the best first step by their supervisor?', options: ['Publicly blame the more junior employee.', 'Ignore the disagreement until the next deadline is missed.', 'Have both reconstruct the agreed handoff steps and evidence before assigning blame.', 'Ask each person to argue separately without comparing facts.'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Reconstructing the shared process and evidence focuses the discussion on what happened before conclusions about responsibility.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q041', section: 'General Aptitude Test', topic: 'हिंदी व्याकरण', difficulty: 'hard', question: 'A public-works monitoring team records these facts. कौन-सा वाक्य सर्वनाम-संदर्भ की दृष्टि से सबसे स्पष्ट है? Use the given values without importing any unstated exception.', options: ['सीमा ने रीना से कहा कि सीमा कल आएगी।', 'अधिकारी ने कर्मचारी से कहा कि वह तैयार है।', 'मोहन ने सोहन को बताया कि वह देर से आया।', 'सीमा ने रीना से कहा कि वह कल आएगी।'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'नाम दोहराने से यह अस्पष्टता समाप्त हो जाती है कि “वह” किसके लिए प्रयुक्त है।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q042', section: 'General Aptitude Test', topic: 'Ratio and proportion', difficulty: 'medium', question: 'During a state-service problem-solving drill, A stock of 560 kg is split between units X and Y in the ratio 6:8. How many kilograms go to X? The state academy requires a conclusion from the stated data alone.', options: ['240', '40', '320', '420'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'X gets 6 of 14 ratio parts: 560×6/14=240 kg.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q043', section: 'General Aptitude Test', topic: 'Data sufficiency', difficulty: 'hard', question: 'What is the value of x?\nI. x is an even integer between 10 and 16.\nII. x is divisible by 3.', options: ['Statement I alone is sufficient.', 'Statement II alone is sufficient.', 'Even together, the statements are not sufficient.', 'Both statements together are sufficient, but neither alone is sufficient.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'I gives x∈{12,14}; II alone has many possibilities. Together only x=12.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q044', section: 'General Aptitude Test', topic: 'Probability', difficulty: 'easy', question: 'A bag contains 3 red, 2 blue and 5 green tokens. One token is drawn at random. What is the probability it is not green?', options: ['1/5', '3/10', '1/2', '2/3'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'There are 5 non-green tokens out of 10 total, so probability=5/10=1/2.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q045', section: 'General Aptitude Test', topic: 'Problem solving', difficulty: 'medium', question: 'A state data-review team is given this case. A pilot change improves speed but increases error rates. What is the best next step? The state academy requires a conclusion from the stated data alone.', options: ['Cancel all future pilots.', 'Evaluate both speed and accuracy against the agreed success criteria before scaling up.', 'Ignore the error increase.', 'Scale immediately because speed improved.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'A pilot should be judged against all relevant success criteria, not one favourable metric alone.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q046', section: 'General Aptitude Test', topic: 'Mixtures', difficulty: 'hard', question: 'A 40-litre solution contains 25% concentrate. How many litres of pure concentrate must be added to make the mixture 40% concentrate?', options: ['6 litres', '10 litres', '8 litres', '12 litres'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Initial concentrate=10 L. If x is added, (10+x)/(40+x)=0.4, giving x=10 L.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q047', section: 'General Aptitude Test', topic: 'Sets and Venn diagrams', difficulty: 'medium', question: 'In a group of 80 people, 46 know Excel, 35 know SQL and 18 know both. How many know neither?', options: ['9', '27', '17', '31'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Know at least one=46+35−18=63; neither=80−63=17.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q048', section: 'General Aptitude Test', topic: 'Interpersonal communication', difficulty: 'medium', question: 'Two colleagues disagree sharply about whether to prioritize speed or completeness in a report. Which response best helps them move toward a workable resolution?', options: ['Tell both that disagreement is unprofessional and end the discussion.', 'Choose the louder speaker\'s proposal to save time.', 'Avoid discussing the trade-off and combine both drafts without review.', 'Ask each to restate the other\'s concern, then identify the minimum accuracy standard and the actual deadline.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Restating each concern checks understanding, while clarifying non-negotiable standards and deadlines turns the disagreement into a solvable trade-off.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q049', section: 'General Aptitude Test', topic: 'Prime factorization', difficulty: 'hard', question: 'How many positive divisors does 360 have?', options: ['18', '20', '24', '30'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: '360 = 2^3×3^2×5^1. The number of positive divisors is (3+1)(2+1)(1+1)=4×3×2=24.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q050', section: 'General Aptitude Test', topic: 'Hindi comprehension', difficulty: 'medium', question: 'एक किसान-सेवा केंद्र ने बीज के प्रत्येक पैकेट पर फसल, उपयुक्त बुवाई-माह और न्यूनतम अंकुरण प्रतिशत बड़े अक्षरों में लिखना शुरू किया। अगले मौसम में गलत महीने में बोए गए पैकेटों से जुड़ी शिकायतें घटीं, जबकि बेचे गए पैकेटों की कुल संख्या लगभग समान रही।\n\nसबसे उचित निष्कर्ष क्या है?', options: ['स्पष्ट समय-संबंधी लेबल ने गलत बुवाई-माह से जुड़ी कुछ गलतियों को कम करने में मदद की।', 'बीज की बिक्री बंद हो गई।', 'हर शिकायत केवल अंकुरण प्रतिशत के कारण होती है।', 'लेबल से मौसम बदल गया।'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'कुल बिक्री लगभग समान रही लेकिन गलत बुवाई-माह वाली शिकायतें घटीं, इसलिए स्पष्ट समय-संबंधी लेबल ने उस विशिष्ट त्रुटि को कम करने में मदद की।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q051', section: 'General Aptitude Test', topic: 'Ages', difficulty: 'medium', question: 'A mother is three times her daughter\'s age. In 12 years she will be twice her daughter\'s age. How old is the daughter now?', options: ['12 years', '8 years', '10 years', '14 years'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Let daughter=x; mother=3x. 3x+12=2(x+12), so x=12.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q052', section: 'General Aptitude Test', topic: 'Problem solving', difficulty: 'medium', question: 'A centre has 90 appointment slots. Thirty are reserved for seniors, 20 for persons with disabilities, and the remaining slots are general. If 26 senior slots and 18 disability slots are used, how many total slots remain unused if all general slots are filled?', options: ['4', '10', '46', '6'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'General slots = 90−30−20=40 and are all filled. Unused reserved slots are 4 senior plus 2 disability = 6.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q053', section: 'General Aptitude Test', topic: 'Hindi comprehension', difficulty: 'medium', question: 'एक ग्रामीण जल-समिति ने हर हैंडपंप की मरम्मत-तिथि और अगली जाँच की तिथि सार्वजनिक बोर्ड पर लिखनी शुरू की। इसके बाद निर्धारित जाँचों में देरी कम हुई, हालांकि कुल हैंडपंपों की संख्या नहीं बदली।\n\nइससे कौन-सा निष्कर्ष सबसे उचित है?', options: ['बोर्ड लगाने से हैंडपंपों की संख्या बढ़ गई।', 'दृश्य समय-सारणी ने जाँच की जवाबदेही और समयपालन में मदद की।', 'मरम्मत की अब आवश्यकता नहीं रही।', 'देरी केवल हैंडपंपों की संख्या के कारण होती है।'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'हैंडपंपों की संख्या स्थिर रहते हुए जाँच-देरी का घटना समय-सारणी की दृश्यता और जवाबदेही से संगत है।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q054', section: 'General Aptitude Test', topic: 'Hindi comprehension', difficulty: 'medium', question: 'एक नगर पुस्तकालय ने देखा कि कई पाठक आरक्षित पुस्तक लेने की अंतिम तिथि भूल जाते हैं। उसने अंतिम तिथि से एक दिन पहले संदेश भेजना शुरू किया। इसके बाद बिना लिए रह जाने वाली आरक्षित पुस्तकों की संख्या घटी।\n\nगद्यांश से कौन-सा निष्कर्ष सबसे उचित है?', options: ['समय पर भेजा गया स्मरण-संदेश पाठकों को अंतिम तिथि से पहले कार्रवाई करने में मदद कर सकता है।', 'पुस्तकालय ने आरक्षण सेवा बंद कर दी।', 'हर संदेश मिलने पर प्रत्येक पाठक अवश्य पुस्तक लेता है।', 'सिर्फ पुस्तकालय का समय बढ़ाने से यह परिवर्तन हुआ।'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'गद्यांश में बदला गया उपाय स्मरण-संदेश है और उसके बाद छूटी हुई आरक्षित पुस्तकों की संख्या कम हुई।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q055', section: 'General Aptitude Test', topic: 'Digit reasoning', difficulty: 'medium', question: 'A regional programme office faces this situation. A two-digit number has tens digit 6 and a units digit 3 greater than the tens digit. By how much does the number increase when its digits are reversed? Assume the listed conditions are exhaustive for this exercise.', options: ['3', '36', '69', '27'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Reversal changes the number by 9×(units−tens) = 9×3 = 27.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q056', section: 'General Aptitude Test', topic: 'Critical reasoning', difficulty: 'hard', question: 'A department claims that a new online form reduced application errors because the overall rejection rate fell after the form was introduced. Which fact would most weaken that causal claim?', options: ['The new form uses a different font.', 'At the same time, the department stopped rejecting applications for two minor errors that had previously caused many rejections.', 'Applicants can access the form from mobile phones.', 'The department published the rejection rate in its annual report.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'If rejection rules were relaxed at the same time, the lower rejection rate could result from the rule change rather than from fewer application errors caused by the form.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q057', section: 'General Aptitude Test', topic: 'Averages', difficulty: 'medium', question: 'A state data-review team is given this case. The average score of 20 trainees is 20. One new trainee with score 38 joins. What is the new average? The state academy requires a conclusion from the stated data alone.', options: ['21.86', '20.86', '29', '21.81'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Old total = 20×20=400. New average = (400+38)/21=20.86.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q058', section: 'General Aptitude Test', topic: 'Scheduling', difficulty: 'hard', question: 'In a public-administration workshop, Meetings A, B and C occupy consecutive one-hour slots. A cannot be first. B must be before C. Which schedule is possible? Assume the listed conditions are exhaustive for this exercise.', options: ['A, B, C', 'C, B, A', 'B, A, C', 'A, C, B'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'B,A,C satisfies A not first and B before C; each alternative breaks one condition.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q059', section: 'General Aptitude Test', topic: 'Coordinate geometry', difficulty: 'easy', question: 'On a coordinate grid, relay point R is exactly halfway between A(−6, 8) and B(10, −4). What are the coordinates of R?', options: ['(4, 2)', '(2, 4)', '(2, 2)', '(8, −2)'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The midpoint is ((−6+10)/2, (8−4)/2) = (2, 2).', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q060', section: 'General Aptitude Test', topic: 'Number process', difficulty: 'medium', question: 'A digital archive assigns the next batch number by adding the sum of the current number’s digits to the current number. Starting from 38, what is the third batch number after 38?', options: ['66', '68', '69', '70'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'From 38, the next number is 38+(3+8)=49; then 49+(4+9)=62; then 62+(6+2)=70. Thus the third batch number after 38 is 70.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q061', section: 'General Aptitude Test', topic: 'Causal inference', difficulty: 'hard', question: 'A call centre changed its script on 1 July. Average call duration fell immediately that week. However, call duration had already been falling steadily for six weeks before 1 July. Which additional evidence would most strengthen the claim that the script itself caused an extra reduction?', options: ['A graph showing only the lower July average.', 'A statement that managers liked the new script.', 'A comparable centre without the script change continued along the earlier downward trend while the changed centre dropped noticeably below its prior trend.', 'Proof that July had the same number of calendar days as June.'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'A comparable untreated centre and a divergence from the pre-existing trend provide a stronger counterfactual for the script\'s causal effect.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q062', section: 'General Aptitude Test', topic: 'Arithmetic', difficulty: 'medium', question: 'A warehouse receives 480 units. It ships 3/8 of them in the morning and 25% of the remainder in the afternoon. How many units remain?', options: ['225', '180', '240', '300'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Morning ships 180, leaving 300. Afternoon ships 75, leaving 225.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q063', section: 'General Aptitude Test', topic: 'Hindi comprehension', difficulty: 'medium', question: 'एक प्राथमिक स्वास्थ्य केंद्र ने पंजीकरण पर्ची पर दवा-एलर्जी पूछने के लिए अलग, स्पष्ट खाँचा जोड़ा। अगले महीने अधूरी एलर्जी-सूचना वाली पर्चियों का अनुपात घटा, जबकि कुल मरीजों की संख्या लगभग समान रही।\n\nसबसे सीधा निष्कर्ष क्या है?', options: ['स्पष्ट खाँचे ने जरूरी एलर्जी-सूचना दर्ज होने की संभावना बढ़ाई।', 'कुल मरीजों की संख्या आधी हो गई।', 'सभी मरीजों को एलर्जी है।', 'एलर्जी-सूचना का उपचार से कोई संबंध नहीं है।'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'रोगी संख्या लगभग स्थिर रहते हुए अधूरी एलर्जी-सूचना का अनुपात घटना स्पष्ट खाँचे के प्रभाव से संगत है।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q064', section: 'General Aptitude Test', topic: 'Hindi comprehension', difficulty: 'medium', question: 'एक स्वास्थ्य केंद्र ने पंजीकरण कक्ष के बाहर आवश्यक दस्तावेज़ों की स्पष्ट सूची लगा दी। पहले लोग बार-बार काउंटर पर पूछते थे कि कौन-सा दस्तावेज़ चाहिए। सूची लगने के बाद ऐसे प्रश्न कम हुए।\n\nमुख्य विचार क्या है?', options: ['दस्तावेज़ों की आवश्यकता समाप्त कर दी गई।', 'काउंटर बंद कर दिया गया।', 'लोगों को कोई सूचना नहीं देनी चाहिए।', 'आवश्यक जानकारी पहले से स्पष्ट कर देने से दोहराव वाले प्रश्न कम हो सकते हैं।'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'स्पष्ट सूची ने वही जानकारी पहले उपलब्ध करा दी जिसके लिए लोग बार-बार पूछते थे।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q065', section: 'General Aptitude Test', topic: 'Process sequencing', difficulty: 'medium', question: 'For an inspection case, four steps must occur subject to these rules: evidence collection (E) must precede analysis (A); legal review (L) must occur after A; notice (N) may be issued only after both A and L. Which sequence is valid?', options: ['E, A, L, N', 'A, E, L, N', 'E, L, A, N', 'E, A, N, L'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'E must come before A, then L after A, and N only after both A and L; E, A, L, N is the only option satisfying all rules.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q066', section: 'General Aptitude Test', topic: 'Problem solving', difficulty: 'medium', question: 'During a state-service problem-solving drill, Two data sources give different totals for the same month. What should be done before choosing either figure? The state academy requires a conclusion from the stated data alone.', options: ['Average the two figures automatically.', 'Check definitions, coverage periods and update times for both sources.', 'Delete both sources.', 'Use the larger figure because it looks safer.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Different definitions or time windows often explain discrepancies; these should be reconciled first.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q067', section: 'General Aptitude Test', topic: 'Odd relationship', difficulty: 'easy', question: 'A regional programme office faces this situation. Which pair has a different relationship from the others? Assume the listed conditions are exhaustive for this exercise.', options: ['Map : Temperature', 'Clock : Time', 'Scale : Weight', 'Thermometer : Temperature'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'A clock measures time, thermometer temperature, and scale weight. A map does not measure temperature.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q068', section: 'General Aptitude Test', topic: 'Statement and assumption', difficulty: 'hard', question: 'Statement: \'Install the update before Friday so the payroll file can be generated with the new tax table.\' Which assumption is necessary?', options: ['Every software update changes payroll tax.', 'The payroll generation after Friday is expected to use the new tax table.', 'The payroll file can never be generated before Friday.', 'All employees use the same computer.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The instruction makes sense only if the upcoming payroll generation requires the new tax table supplied by the update.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q069', section: 'General Aptitude Test', topic: 'Quantitative reasoning', difficulty: 'hard', question: 'A quantity x satisfies x/3 + x/4 = 35. What is x?', options: ['48', '72', '84', '60'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: '7x/12=35, so x=60.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q070', section: 'General Aptitude Test', topic: 'Pattern recognition', difficulty: 'medium', question: 'In a public-administration workshop, The sequence of symbols repeats in groups of four: ○, △, □, ☆, ○, △, □, ☆, … What is the 19th symbol? Assume the listed conditions are exhaustive for this exercise.', options: ['□', '○', '☆', '△'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: '19 leaves remainder 3 when divided by 4, so it corresponds to the third symbol, □.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q071', section: 'General Aptitude Test', topic: 'Set reasoning', difficulty: 'medium', question: 'Every certified guide is trained. Some trained people are volunteers. Which statement must be true?', options: ['Some volunteers are certified guides.', 'All certified guides are trained.', 'No trained person is a volunteer.', 'All volunteers are certified guides.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The first sentence directly states the only necessary conclusion; the overlap between trained people and volunteers does not locate certified guides.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q072', section: 'General Aptitude Test', topic: 'Comprehension and operations', difficulty: 'medium', question: 'A vaccine store orders supplies when stock falls to a reorder point calculated from normal daily use and delivery lead time. After deliveries began taking two extra days, stock-outs increased even though daily use stayed stable. The store then raised the reorder point.\n\nWhat problem was the change designed to address?', options: ['The old reorder point no longer covered the longer delivery lead time.', 'Daily vaccine use had become zero.', 'Raising the reorder point shortens the physical distance to the supplier.', 'The store was receiving too many same-day deliveries.'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'With stable daily use but a longer lead time, more stock is needed on hand when reordering to cover consumption until delivery.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q073', section: 'General Aptitude Test', topic: 'हिंदी प्रयोग', difficulty: 'medium', question: 'During a forest-division planning review, सही वर्तनी चुनिए। Assume the listed conditions are exhaustive for this exercise.', options: ['आवश्यक्य', 'आवष्यक', 'अवश्यक', 'आवश्यक'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'मानक वर्तनी “आवश्यक” है।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q074', section: 'General Aptitude Test', topic: 'Compound interest', difficulty: 'medium', question: '₹10,000 is invested at 10% compound interest annually for 2 years. What is the amount?', options: ['₹12,000', '₹12,100', '₹11,000', '₹12,200'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Amount=10000×1.1²=₹12,100.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q075', section: 'General Aptitude Test', topic: 'Decision making', difficulty: 'hard', question: 'A relief warehouse has one vehicle left. One delivery restores drinking water to an isolated hamlet; another replenishes non-urgent stationery at an office. Both requests are valid. Which dispatch is most defensible?', options: ['Choose the stationery because the office submitted its request first.', 'Split the vehicle into two deliveries at the same time.', 'Make no delivery because both requests are valid.', 'Send the vehicle to restore drinking water, while rescheduling the non-urgent stationery delivery.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'With one scarce vehicle, the immediate essential-service need has greater urgency, while the routine delivery can be rescheduled.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q076', section: 'General Aptitude Test', topic: 'Hindi comprehension', difficulty: 'medium', question: 'एक प्रशिक्षण कार्यक्रम में प्रतिभागियों को केवल व्याख्यान सुनाने के बजाय छोटे अभ्यास दिए गए। अगली बैठक में उन्होंने बताया कि वास्तविक काम में कौन-सी कठिनाई आई। प्रशिक्षक ने उसी आधार पर अगला अभ्यास बदला।\n\nयह किस प्रकार की सीख को दर्शाता है?', options: ['हर बार वही अभ्यास दोहराना।', 'केवल परीक्षा अंक देखना।', 'प्रयोग और प्रतिक्रिया के आधार पर प्रशिक्षण को अनुकूलित करना।', 'प्रतिभागियों की प्रतिक्रिया को अनदेखा करना।'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'उत्तर गद्यांश में दिए गए मुख्य कारण और परिणाम के संबंध से निकलता है।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q077', section: 'General Aptitude Test', topic: 'Counting', difficulty: 'medium', question: 'How many three-letter codes can be formed from A, B, C, D if letters cannot repeat?', options: ['24', '12', '16', '64'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'There are 4 choices, then 3, then 2: 4×3×2=24.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q078', section: 'General Aptitude Test', topic: 'Work rate', difficulty: 'medium', question: 'Machine A processes 30 forms per hour and B processes 20. They work together for 3 hours, after which A stops. How long must B work alone to reach 210 forms in total?', options: ['1 hour', '3 hours', '2 hours', '4 hours'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Together they process 150 forms in 3 hours. B must process 60 more at 20 per hour, needing 3 hours.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q079', section: 'General Aptitude Test', topic: 'Hindi comprehension', difficulty: 'medium', question: 'एक किसान समूह ने तीन खेतों में एक ही बीज लगाया, पर पानी की मात्रा अलग रखी। उपज में अंतर मिलने पर समूह ने कहा कि निष्कर्ष निकालने से पहले मिट्टी की गुणवत्ता भी जाँचनी चाहिए।\n\nयह सावधानी क्यों उचित है?', options: ['पानी का उपज से कभी संबंध नहीं होता।', 'तीनों खेतों की मिट्टी अवश्य समान थी।', 'मिट्टी की गुणवत्ता भी उपज को प्रभावित कर सकती है, इसलिए केवल पानी को कारण मानना जल्दबाज़ी होगी।', 'उपज का अंतर किसी भी कारण से नहीं हो सकता।'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'पानी के साथ मिट्टी भी संभावित प्रभावकारी कारक है, इसलिए कारण तय करने से पहले उसे जाँचना उचित है।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q080', section: 'General Aptitude Test', topic: 'Comprehension and data quality', difficulty: 'medium', question: 'A land-records team digitized parcel numbers from paper registers. Before publishing each batch, a second clerk checked a random sample against the originals. If the sample error rate exceeded a preset limit, the entire batch was rechecked.\n\nWhat is the main purpose of this procedure?', options: ['To use sampling as a quality-control trigger before publication.', 'To prove that every unchecked entry is error-free.', 'To eliminate the need for original registers immediately.', 'To increase the number of transcription errors.'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The sample is used to estimate batch quality and trigger a full recheck when observed errors exceed the threshold.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q081', section: 'General Aptitude Test', topic: 'Binary logic', difficulty: 'medium', question: 'A state data-review team is given this case. A gate opens if and only if both switches X and Y are on. X is on and the gate is closed. What must be true? The state academy requires a conclusion from the stated data alone.', options: ['The gate is open.', 'Y is off.', 'Y is on.', 'X is off.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'With X already on, a closed gate means the condition “X and Y both on” is false, so Y must be off.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q082', section: 'General Aptitude Test', topic: 'Family relations', difficulty: 'medium', question: 'Dev says, \'Meera is the sister of my son\'s mother.\' If Dev is male and the son\'s mother is Dev\'s wife, how is Meera related to Dev?', options: ['Daughter', 'Cousin', 'Aunt', 'Sister-in-law'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The son\'s mother is Dev\'s wife; Meera is the wife\'s sister, so Meera is Dev\'s sister-in-law.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q083', section: 'General Aptitude Test', topic: 'Arithmetic reasoning', difficulty: 'medium', question: 'A dispatch desk begins the day with 240 blank forms. In the morning 35 are issued and 12 unused forms are returned. In the afternoon 48 are issued and 5 unused forms are returned. How many blank forms are at the desk at day’s end?', options: ['169', '171', '174', '176'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The closing stock is 240 − 35 + 12 − 48 + 5 = 174 blank forms.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q084', section: 'General Aptitude Test', topic: 'हिंदी मुहावरा', difficulty: 'medium', question: 'A state training academy poses this problem. “आँखों का तारा” मुहावरे का अर्थ है: The state academy requires a conclusion from the stated data alone.', options: ['क्रोधित व्यक्ति', 'बहुत दूर व्यक्ति', 'बहुत प्रिय व्यक्ति', 'अज्ञात व्यक्ति'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: '“आँखों का तारा” अत्यंत प्रिय व्यक्ति के लिए कहा जाता है।', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q085', section: 'General Aptitude Test', topic: 'Comprehension and behavioural response', difficulty: 'medium', question: 'A training portal sent one reminder seven days before a mandatory course deadline. Many users still completed the course on the final day. The next month it sent reminders seven days and two days before the deadline; final-day completions fell, while the total completion rate changed little.\n\nWhat is the strongest supported inference?', options: ['The second reminder made the course optional.', 'Two reminders necessarily increase total completion in every setting.', 'Users forgot the course existed until after the deadline.', 'The added near-deadline reminder shifted some completions earlier without clearly changing the total completion rate.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The total completion rate stayed about the same while fewer completions occurred on the final day, indicating a timing shift.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q086', section: 'General Aptitude Test', topic: 'Comprehension and measurement', difficulty: 'medium', question: 'A town installed district water meters at the inlet of each supply zone. Household-meter totals were then compared with inlet volumes. One zone repeatedly showed a much larger gap than the others, so crews inspected that zone first and found a hidden main leak.\n\nWhat role did the district meters play?', options: ['They helped identify where unaccounted-for water was unusually high, allowing inspection to be prioritized.', 'They repaired the leak automatically.', 'They proved that every household meter was inaccurate.', 'They reduced water demand before any inspection occurred.'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Comparing inlet volume with billed household totals localized an unusually large water-loss gap and guided targeted inspection.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q087', section: 'General Aptitude Test', topic: 'Comprehension', difficulty: 'medium', question: 'A library found that many reserved books were never collected. It began sending a reminder two days before the collection deadline. The number of uncollected reservations fell, while the reservation limit and opening hours stayed unchanged.\n\nWhich inference is best supported by the passage?', options: ['Longer opening hours caused the fall in missed collections.', 'The library stopped allowing reservations.', 'Timely reminders can reduce missed collections even without changing access rules.', 'Every reminder guarantees that a book will be collected.'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The only stated intervention is the advance reminder; the fall in missed collections is consistent with reminders helping users act before the deadline.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q088', section: 'General Aptitude Test', topic: 'Speed, distance and time', difficulty: 'medium', question: 'A patrol starts at 8:15 a.m. and travels 84 km at 56 km/h without stopping. At what time does it arrive?', options: ['9:30 a.m.', '9:45 a.m.', '10:00 a.m.', '10:15 a.m.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Travel time=84/56=1.5 hours. 8:15 + 1 h 30 min = 9:45.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q089', section: 'General Aptitude Test', topic: 'Algebra', difficulty: 'medium', question: 'At a canteen, 2 meal coupons and 3 tea coupons cost ₹210, while 3 meal coupons and 1 tea coupon cost ₹210. What is the price of one meal coupon?', options: ['₹50', '₹60', '₹70', '₹80'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Let meal = m and tea = t. The equations are 2m+3t=210 and 3m+t=210. From the second, t=210-3m. Substituting gives 2m+630-9m=210, so 7m=420 and m=₹60.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q090', section: 'General Aptitude Test', topic: 'Boats and streams', difficulty: 'easy', question: 'A boat moves at 12 km/h in still water and the stream flows at 3 km/h. How long does it take to travel 30 km upstream?', options: ['3⅓ hours', '2 hours', '2½ hours', '4 hours'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Upstream speed=9 km/h, so time=30/9=3⅓ h.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q091', section: 'General Aptitude Test', topic: 'Arithmetic reasoning', difficulty: 'medium', question: 'A parcel service charges ₹40 for the first 2 kg and ₹15 for each additional 0.5 kg or part thereof. What is the charge for a parcel weighing 3.2 kg?', options: ['₹70', '₹75', '₹85', '₹90'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Beyond the first 2 kg, the parcel has 1.2 kg extra. This requires three 0.5 kg charge blocks because any part of a block is charged as a full block. Extra charge = 3×₹15 = ₹45, so total charge = ₹40+₹45 = ₹85.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q092', section: 'General Aptitude Test', topic: 'Comprehension', difficulty: 'medium', question: 'A bridge-maintenance crew moved lane-marking work from the afternoon rush to overnight hours. Portable lighting made the job slower, but queues for daytime commuters were greatly reduced. What trade-off did the crew accept?', options: ['Greater daytime disruption for faster work.', 'No change in either work time or disruption.', 'Eliminating the need for lighting.', 'Longer work time in exchange for less disruption to road users.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The crew accepted longer work time in exchange for less disruption to road users.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q093', section: 'General Aptitude Test', topic: 'Comprehension', difficulty: 'medium', question: 'A training programme reported 500 attendees and initially treated attendance as its main success measure. A later practical assessment found that only 48% of participants could complete the required procedure without help.\n\nWhat does this example suggest about performance measures?', options: ['High attendance by itself proves skill mastery.', 'Outcome measures can reveal weaknesses that activity counts alone hide.', 'Only activity counts should be reported.', 'Competency is unrelated to training.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Attendance measures participation, while the practical assessment measures the intended outcome. The lower competency result reveals a weakness that the activity count alone concealed.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q094', section: 'General Aptitude Test', topic: 'Interpersonal skills', difficulty: 'hard', question: 'In a public-administration workshop, A meeting is dominated by two speakers while others have relevant information. What facilitation move is best? Assume the listed conditions are exhaustive for this exercise.', options: ['Ask quieter members to send comments only after the decision.', 'Let the two speakers make every decision.', 'End the meeting before others speak.', 'Invite input from quieter members and use a structured turn-taking method.'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Structured participation broadens the evidence base and prevents a few voices from crowding out useful information.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q095', section: 'General Aptitude Test', topic: 'Trains', difficulty: 'medium', question: 'A 180 m train moving at 72 km/h passes a pole. How many seconds does it take?', options: ['9 seconds', '6 seconds', '10 seconds', '12 seconds'], correctIndex: 0, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: '72 km/h=20 m/s; time=180/20=9 s.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q096', section: 'General Aptitude Test', topic: 'Data interpretation', difficulty: 'easy', question: 'A state training academy poses this problem. Five response times, in minutes, are [16, 16, 18, 26, 33]. What is the median response time? The state academy requires a conclusion from the stated data alone.', options: ['33', '16', '21.8', '18'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'After ordering the five values as [16, 16, 18, 26, 33], the middle (third) value is 18.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q097', section: 'General Aptitude Test', topic: 'Comprehension', difficulty: 'medium', question: 'During a forest-division planning review, A bus depot compared fuel use across routes. One hilly route used more fuel per kilometre even though its buses carried fewer passengers. Managers avoided blaming drivers until they accounted for gradient, traffic and vehicle age.\n\nWhich principle is illustrated most clearly by the account?\n\nThe state review used the same reporting interval and the same definition of each measured outcome. Use only the facts supplied in the passage and distinguish observation from speculation.', options: ['Lower passenger counts always cause higher fuel use.', 'Performance comparisons should control for relevant differences in operating conditions.', 'Drivers should be judged only by raw fuel totals.', 'Route conditions never affect fuel consumption.'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The answer follows from the central relationship stated in the passage.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q098', section: 'General Aptitude Test', topic: 'Clock reasoning', difficulty: 'medium', question: 'A clock is correct at 9:00 a.m. and then gains 2 minutes every hour. What time will it display when the actual time is 3:00 p.m.?', options: ['2:48 p.m.', '3:02 p.m.', '3:12 p.m.', '3:20 p.m.'], correctIndex: 2, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Six actual hours pass from 9 a.m. to 3 p.m.; at 2 minutes gained per hour the clock gains 12 minutes and shows 3:12 p.m.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q099', section: 'General Aptitude Test', topic: 'Data interpretation', difficulty: 'hard', question: 'A field team records three categories of cases: 30 routine cases averaging 12 minutes each, 20 review cases averaging 18 minutes each, and 10 complex cases averaging 30 minutes each. What is the overall average time per case?', options: ['16 minutes', '17 minutes', '18 minutes', '19 minutes'], correctIndex: 1, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'Total time = 30×12 + 20×18 + 10×30 = 1,020 minutes for 60 cases. The weighted average is 1,020/60 = 17 minutes.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
  { id: 'b15-002-apt-q100', section: 'General Aptitude Test', topic: 'Averages', difficulty: 'medium', question: 'The average processing time for the first four applications is 18 minutes. After a fifth application is included, the average becomes 20 minutes. How long did the fifth application take?', options: ['22 minutes', '24 minutes', '26 minutes', '28 minutes'], correctIndex: 3, answerType: 'mcq', marks: 3.0, negativeMarking: 1.0, explanation: 'The first four total 72 minutes; five at an average of 20 total 100 minutes, so the fifth took 28 minutes.', source: { kind: 'original', reference: 'MPPSC State Service 2026 current cycle', url: 'https://mppsc.mp.gov.in/', checkedOn: '2026-09-10' } },
];
